public async Task<List<EventListItemDto>> GetEventsAsync(DateOnly? from = null, DateOnly? to = null)
{
    var query = dbContext.Events.AsQueryable();

    if (from is not null)
    {
        var fromStart = from.Value.ToDateTime(TimeOnly.MinValue);
        query = query.Where(e => e.Zeitpunkt >= fromStart);
    }

    if (to is not null)
    {
        var toExclusive = to.Value.AddDays(1).ToDateTime(TimeOnly.MinValue);
        query = query.Where(e => e.Zeitpunkt < toExclusive);
    }

    return await query
        .OrderBy(e => e.Zeitpunkt)
        .Select(e => new EventListItemDto(e.Id, e.Titel, e.Venue!.Name, e.Zeitpunkt))
        .ToListAsync();
}

